const envelope = $input || {};
const text = (value) => (typeof value === 'string' ? value.trim() : '');
const envelopeKeys = new Set(['pluginId', 'widgetId', 'product', 'resource', 'submittedBy', 'submittedAt', 'action', 'fields']);
const unknownEnvelope = Object.keys(envelope).filter((key) => !envelopeKeys.has(key));
if (unknownEnvelope.length) throw new Error('unknown_envelope_fields:' + unknownEnvelope.join(','));
const product = text(envelope.product);
const resource = text(envelope.resource);
const submittedBy = text(envelope.submittedBy);
if (!submittedBy) throw new Error('submitted_by_required');
const fields = envelope.fields && typeof envelope.fields === 'object' && !Array.isArray(envelope.fields) ? envelope.fields : null;
if (!fields) throw new Error('fields_required');

if (product !== 'sos') throw new Error('unsupported_product');
if (resource !== 'eop') throw new Error('unsupported_resource');
const planId = text(fields.plan_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(planId)) throw new Error('record_id_invalid');
const approvalId = text(fields.approval_id);
if (!/^[A-Za-z0-9_@.:+-]{1,256}$/.test(approvalId)) throw new Error('approval_id_invalid');
const allowed = new Set(['plan_id', 'approval_id', 'review_notes']);
const unknown = Object.keys(fields).filter((key) => !allowed.has(key));
if (unknown.length) throw new Error('unknown_fields:' + unknown.join(','));
const reviewNotes = text(fields.review_notes);
if (reviewNotes.length > 4000) throw new Error('review_notes_max_4000');
const audit = {
  product, resource, operation: 'eop.approve', recordId: planId,
  pluginId: text(envelope.pluginId), widgetId: text(envelope.widgetId),
  submittedBy, submittedAt: text(envelope.submittedAt) || $now,
};
return { planId, encodedPlanId: encodeURIComponent(planId), approvalId, encodedApprovalId: encodeURIComponent(approvalId), reviewNotes, audit };

const response = $input || {};
const state = response.input;
if (response.statusCode !== 200 || !response.body || typeof response.body !== 'object') throw new Error('approval_not_found');
const approval = response.body.approval && typeof response.body.approval === 'object' ? response.body.approval : response.body;
if (String(approval.status) !== 'approved') throw new Error('approval_not_approved');
if (String(approval.entityId) !== String(state.planId)) throw new Error('approval_entity_mismatch');
if (String(approval.action) !== 'eop.approve') throw new Error('approval_action_mismatch');
// Four-eyes (docs/HITL.md, mirroring assert_approval_ready in the Tier-3
// routes): the operator who requested the approval can never consume it.
if (String(approval.requester) === String(state.audit.submittedBy)) throw new Error('self_approval_forbidden');
return { ...state, approval: { id: approval.id === undefined ? null : String(approval.id), approverRoles: Array.isArray(approval.approverRoles) ? approval.approverRoles.map(String) : [] } };

const response = $input || {};
const state = response.input;
const current = response.body;
if (response.statusCode !== 200 || !current || typeof current.data !== 'object' || !current.data) throw new Error('plan_not_found');
if (!Number.isInteger(current.version)) throw new Error('record_version_unavailable');
const plan = { ...current.data, id: String(current.data.id || current.id) };
const status = String(plan.status);
if (status === 'approved') {
  return { idempotent: true, planId: plan.id, status, approval_id: plan.approval_id === undefined ? null : plan.approval_id, approved_by: plan.approved_by === undefined ? null : plan.approved_by };
}
if (!['draft', 'review_pending'].includes(status)) throw new Error('invalid_eop_status');
const approverRoles = state.approval.approverRoles;
const next = {
  ...plan,
  status: 'approved',
  review_notes: state.reviewNotes || (typeof plan.review_notes === 'string' ? plan.review_notes : null),
  approved_by: state.audit.submittedBy,
  approved_at: $now,
  approval_id: state.approval.id,
  approved_role: approverRoles.length ? approverRoles[0] : null,
  approval_roles: approverRoles,
  updated_at: $now,
};
return { body: { data: next, ifVersion: current.version }, encodedId: state.encodedPlanId, audit: state.audit, operation: 'eop.approve' };

const state = $input || {};
if (state.idempotent !== true) throw new Error('unexpected_approval_mode');
return {
  idempotent: true, operation: 'eop.approve', plan_id: state.planId, status: 'approved',
  approval_id: state.approval_id, approved_by: state.approved_by,
};
